package com.example.simpleaccountant.ui.suppliers;import android.os.Bundle;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import com.example.simpleaccountant.R;import com.example.simpleaccountant.data.dao.SupplierDao;import com.example.simpleaccountant.data.model.Supplier;
public class AddSupplierActivity extends AppCompatActivity {@Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_add_supplier);SupplierDao dao=new SupplierDao(this);EditText n=findViewById(R.id.etName),p=findViewById(R.id.etPhone),e=findViewById(R.id.etEmail),a=findViewById(R.id.etAddress),no=findViewById(R.id.etNote);findViewById(R.id.btnSave).setOnClickListener(v->{if(n.getText().toString().trim().isEmpty()){n.setError("Required");return;}Supplier s=new Supplier();s.setName(n.getText().toString().trim());s.setPhone(p.getText().toString().trim());s.setEmail(e.getText().toString().trim());s.setAddress(a.getText().toString().trim());s.setNote(no.getText().toString().trim());dao.insertSupplier(s);Toast.makeText(this,"Saved",Toast.LENGTH_SHORT).show();finish();});}}
